      backup_text =
        "# Moonlit Field Plotter #\n\
         # Crops advance through growth stages #\n\n\
         type GrowthStage =\n\
         + Seed\n\
         + Sprout\n\
         + Growing\n\
         + Mature\n\
         + ReadyToHarvest\n\
         in\n\n\
         type CropKind =\n\
         + Moonmelon\n\
         + Nightshade\n\
         + Starfruit\n\
         + Glowpumpkin\n\
         + Duskwheat\n\
         in\n\n\
         type Cell =\n\
         + Empty\n\
         + Planted(CropKind, GrowthStage)\n\
         in\n\n\
         type Row = Int in\n\
         type Col = Int in\n\n\
         type Field = [[Cell]] in\n\n\
         type Model = (\n\
         field = Field,\n\
         currentSeed = CropKind,\n\
         dayCount = Int\n\
         ) in\n\n\
         type Action =\n\
         + PlantCrop(Row, Col)\n\
         + HarvestCrop(Row, Col)\n\
         + WaterField\n\
         + PassDay\n\
         + SelectSeed(CropKind)\n\
         in\n\n\
         let advanceStage : GrowthStage -> GrowthStage =\n\
         fun stage ->\n\
         case stage\n\
         | Seed => Sprout\n\
         | Sprout => Growing\n\
         | Growing => Growing\n\
         | Mature => ReadyToHarvest\n\
         | ReadyToHarvest => ReadyToHarvest\n\
         end\n\
         in\n\n\
         let isPlanted : Cell -> Bool =\n\
         fun cell ->\n\
         case cell\n\
         | Empty => false\n\
         | Planted(_, _) => true\n\
         end\n\
         in\n\n\
         let isHarvestable : Cell -> Bool =\n\
         fun cell ->\n\
         case cell\n\
         | Empty => false\n\
         | Planted(_, stage) =>\n\
         case stage\n\
         | ReadyToHarvest => true\n\
         | _ => false\n\
         end\n\
         end\n\
         in\n\n\
         let getStage : Cell -> GrowthStage =\n\
         fun cell ->\n\
         case cell\n\
         | Empty => Seed\n\
         | Planted(_, stage) => stage\n\
         end\n\
         in\n\n\
         let waterCell : Cell -> Cell =\n\
         fun cell ->\n\
         case cell\n\
         | Empty => Empty\n\
         | Planted(crop, stage) => Planted(crop, advanceStage(stage))\n\
         end\n\
         in\n\n\
         let waterField : Field -> Field =\n\
         fun field ->\n\
         map(field, fun row ->\n\
         map(row, fun cell -> waterCell(cell))\n\
         )\n\
         in\n\n\
         let getCell : (Field, Row, Col) -> Cell =\n\
         fun (field, row, col) ->\n\
         nth(nth(field, row), col)\n\
         in\n\n\
         let setCell : (Field, Row, Col, Cell) -> Field =\n\
         fun (field, targetRow, targetCol, newCell) ->\n\
         mapi(field, fun (r, row) ->\n\
         mapi(row, fun (c, cell) ->\n\
         if r == targetRow && c == targetCol\n\
         then newCell\n\
         else cell\n\
         )\n\
         )\n\
         in\n\n\
         let makeField : (Int, Int) -> Field =\n\
         fun (rows, cols) ->\n\
         map(range(0, rows - 1), fun _ ->\n\
         map(range(0, cols - 1), fun _ -> Empty)\n\
         )\n\
         in\n\n\
         let initModel : Model = (\n\
         field = makeField(4, 4),\n\
         currentSeed = Moonmelon,\n\
         dayCount = 0\n\
         ) in\n\n\
         let plantAt : (Model, Row, Col) -> Model =\n\
         fun (model, row, col) ->\n\
         let cell = getCell(model.field, row, col) in\n\
         if isPlanted(cell)\n\
         then model\n\
         else\n\
         let newCell = Planted(model.currentSeed, Seed) in\n\
         let newField = setCell(model.field, row, col, newCell) in\n\
         (field = newField, currentSeed = model.currentSeed, dayCount = \
         model.dayCount)\n\
         in\n\n\
         let harvestAt : (Model, Row, Col) -> Model =\n\
         fun (model, row, col) ->\n\
         let cell = getCell(model.field, row, col) in\n\
         if isHarvestable(cell)\n\
         then\n\
         let newField = setCell(model.field, row, col, Empty) in\n\
         (field = newField, currentSeed = model.currentSeed, dayCount = \
         model.dayCount)\n\
         else model\n\
         in\n\n\
         let update : (Model, Action) -> Model =\n\
         fun (model, action) ->\n\
         case action\n\
         | PlantCrop(row, col) => plantAt(model, row, col)\n\
         | HarvestCrop(row, col) => harvestAt(model, row, col)\n\
         | WaterField =>\n\
         let newField = waterField(model.field) in\n\
         (field = newField, currentSeed = model.currentSeed, dayCount = \
         model.dayCount)\n\
         | PassDay =>\n\
         (field = model.field, currentSeed = model.currentSeed, dayCount = \
         model.dayCount + 1)\n\
         | SelectSeed(crop) =>\n\
         (field = model.field, currentSeed = crop, dayCount = model.dayCount)\n\
         end\n\
         in\n\n\
         let run : (Model, [Action]) -> Model =\n\
         fun (model, actions) ->\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         let countAtStage : (Field, GrowthStage) -> Int =\n\
         fun (field, targetStage) ->\n\
         fold_left(field, fun (acc, row) ->\n\
         acc + fold_left(row, fun (acc2, cell) ->\n\
         if isPlanted(cell) && getStage(cell) == targetStage\n\
         then acc2 + 1\n\
         else acc2\n\
         , 0)\n\
         , 0)\n\
         in\n\n\
         let countPlanted : Field -> Int =\n\
         fun field ->\n\
         fold_left(field, fun (acc, row) ->\n\
         acc + fold_left(row, fun (acc2, cell) ->\n\
         if isPlanted(cell) then acc2 + 1 else acc2\n\
         , 0)\n\
         , 0)\n\
         in\n\n\
         let countHarvestable : Field -> Int =\n\
         fun field -> countAtStage(field, ReadyToHarvest)\n\
         in\n\n\
         let getCropKind : Cell -> CropKind =\n\
         fun cell ->\n\
         case cell\n\
         | Empty => Moonmelon\n\
         | Planted(crop, _) => crop\n\
         end\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         hint \"can plant a crop in empty cell\"\n\
         test\n\
         let m = update(initModel, PlantCrop(0, 0)) in\n\
         isPlanted(getCell(m.field, 0, 0))\n\
         end;\n\n\
         hint \"planted crop starts at Seed stage\"\n\
         test\n\
         let m = update(initModel, PlantCrop(1, 1)) in\n\
         let cell = getCell(m.field, 1, 1) in\n\
         getStage(cell) == Seed\n\
         end;\n\n\
         hint \"cannot plant on occupied cell\"\n\
         test\n\
         let m = run(initModel, [PlantCrop(0, 0), PlantCrop(0, 0)]) in\n\
         countPlanted(m.field) == 1\n\
         end;\n\n\
         hint \"can select different seed types\"\n\
         test\n\
         let m = run(initModel, [\n\
         SelectSeed(Nightshade),\n\
         PlantCrop(0, 0)\n\
         ]) in\n\
         let cell = getCell(m.field, 0, 0) in\n\
         getCropKind(cell) == Nightshade\n\
         end;\n\n\
         hint \"advanceStage: Seed becomes Sprout\"\n\
         test advanceStage(Seed) == Sprout end;\n\n\
         hint \"advanceStage: Sprout becomes Growing\"\n\
         test advanceStage(Sprout) == Growing end;\n\n\
         hint \"advanceStage: Growing becomes Mature\"\n\
         test advanceStage(Growing) == Mature end;\n\n\
         hint \"advanceStage: Mature becomes ReadyToHarvest\"\n\
         test advanceStage(Mature) == ReadyToHarvest end;\n\n\
         hint \"advanceStage: ReadyToHarvest stays ReadyToHarvest\"\n\
         test advanceStage(ReadyToHarvest) == ReadyToHarvest end;\n\n\
         hint \"watering advances planted crops\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         WaterField\n\
         ]) in\n\
         let cell = getCell(m.field, 0, 0) in\n\
         getStage(cell) == Sprout\n\
         end;\n\n\
         hint \"watering does not affect empty cells\"\n\
         test\n\
         let m = run(initModel, [WaterField, WaterField, WaterField]) in\n\
         let cell = getCell(m.field, 2, 2) in\n\
         !isPlanted(cell)\n\
         end;\n\n\
         hint \"multiple waterings progress through stages\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         WaterField, WaterField, WaterField, WaterField\n\
         ]) in\n\
         let cell = getCell(m.field, 0, 0) in\n\
         getStage(cell) == ReadyToHarvest\n\
         end;\n\n\
         hint \"can harvest ReadyToHarvest crops\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         WaterField, WaterField, WaterField, WaterField,\n\
         HarvestCrop(0, 0)\n\
         ]) in\n\
         !isPlanted(getCell(m.field, 0, 0))\n\
         end;\n\n\
         hint \"cannot harvest immature crops\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         WaterField,\n\
         HarvestCrop(0, 0)\n\
         ]) in\n\
         isPlanted(getCell(m.field, 0, 0))\n\
         end;\n\n\
         hint \"harvesting clears the cell\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(1, 1),\n\
         WaterField, WaterField, WaterField, WaterField,\n\
         HarvestCrop(1, 1)\n\
         ]) in\n\
         let cell = getCell(m.field, 1, 1) in\n\
         cell == Empty\n\
         end;\n\n\
         hint \"PassDay increments day count\"\n\
         test\n\
         let m = run(initModel, [PassDay, PassDay, PassDay]) in\n\
         m.dayCount == 3\n\
         end;\n\n\
         hint \"can plant multiple crops\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         PlantCrop(0, 1),\n\
         PlantCrop(1, 0)\n\
         ]) in\n\
         countPlanted(m.field) == 3\n\
         end;\n\n\
         hint \"watering advances all crops simultaneously\"\n\
         test\n\
         let m = run(initModel, [\n\
         PlantCrop(0, 0),\n\
         PlantCrop(1, 1),\n\
         WaterField\n\
         ]) in\n\
         let c1 = getCell(m.field, 0, 0) in\n\
         let c2 = getCell(m.field, 1, 1) in\n\
         getStage(c1) == Sprout && getStage(c2) == Sprout\n\
         end;\n\n\
         let gardenDemo = run(initModel, [\n\
         SelectSeed(Moonmelon),\n\
         PlantCrop(0, 0),\n\
         SelectSeed(Nightshade),\n\
         PlantCrop(0, 1),\n\
         SelectSeed(Starfruit),\n\
         PlantCrop(1, 0),\n\
         SelectSeed(Glowpumpkin),\n\
         PlantCrop(1, 1),\n\
         WaterField, PassDay,\n\
         WaterField, PassDay,\n\
         WaterField, PassDay,\n\
         WaterField, PassDay,\n\
         HarvestCrop(0, 0),\n\
         HarvestCrop(0, 1)\n\
         ]) in\n\
         gardenDemo\n";
      refractors = "()";
    } )
